class Solution {
  public int minimumCost(int[] start, int[] target, int[][] specialRoads) {
    int k = specialRoads.length, v = 2 * k + 2;
    int[] xs = new int[v], ys = new int[v];
    xs[0] = start[0];
    ys[0] = start[1];
    xs[1] = target[0];
    ys[1] = target[1];
    for (int i = 0; i < k; i++) {
      xs[2 * i + 2] = specialRoads[i][0];
      ys[2 * i + 2] = specialRoads[i][1];
      xs[2 * i + 3] = specialRoads[i][2];
      ys[2 * i + 3] = specialRoads[i][3];
    }
    int[] dist = new int[v];
    boolean[] done = new boolean[v];
    java.util.Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    for (int it = 0; it < v; it++) {
      int u = -1;
      for (int i = 0; i < v; i++) if (!done[i] && (u < 0 || dist[i] < dist[u])) u = i;
      if (u == 1) break;
      done[u] = true;
      for (int w = 0; w < v; w++) {
        if (done[w]) continue;
        int d = dist[u] + Math.abs(xs[u] - xs[w]) + Math.abs(ys[u] - ys[w]);
        if (d < dist[w]) dist[w] = d;
      }
      if (u >= 2 && u % 2 == 0) {
        int d = dist[u] + specialRoads[(u - 2) / 2][4];
        if (d < dist[u + 1]) dist[u + 1] = d;
      }
    }
    return dist[1];
  }
}
